type Job={slug:string;keyword:string;make:string;model:string;category:string;title:string;answer:string;scope:string;detail:string;values:SpecValue[];source:Source;sources?:Source[];reviewed?:string;diagram?:"wheel"|"spark"|"firing"|"oil"|"timing"|"main";engine?:boolean};
const jobs:Job[]=[
  {slug:"hyundai/kona/oil-capacity",keyword:"hyundai kona oil capacity specifications",make:"Hyundai",model:"2024 Kona",category:"Fluid Capacities",title:"2024 Hyundai Kona Oil Capacity: 2.0L vs. 1.6 Turbo",answer:"For a drain-and-refill, Hyundai specifies 4.5 US qt (4.3 L) for the 2024 Kona Smartstream 2.0L Atkinson engine and 5.1 US qt (4.8 L) for the Smartstream 1.6L T-GDi.",scope:"These values are from the U.S.-market 2024 SX2 Kona manual. They do not apply to the electric Kona, Kona N, another market's 1.0L engine or an earlier generation. Identify the engine before opening bottles because the two gasoline rows differ by 0.6 qt.",detail:"Both gasoline engines call for full-synthetic SAE 0W-20 meeting API SN PLUS/SP or ILSAC GF-6 in this manual. Treat the listed amount as a refill reference: install the correct filter and drain-plug sealing part, add most of the quantity, circulate the oil, inspect for leaks, wait on level ground and finish at the dipstick mark. Never force the entire bottle count into an engine already reading full.",values:[{label:"2.0L Atkinson drain-and-refill",value:"4.5 US qt",note:"4.3 L"},{label:"1.6L T-GDi drain-and-refill",value:"5.1 US qt",note:"4.8 L"},{label:"Required viscosity",value:"SAE 0W-20",note:"Both gasoline engine rows"},{label:"Oil quality",value:"API SN PLUS/SP or ILSAC GF-6",note:"Full synthetic required"}],source:hyundaiKona2024,diagram:"oil"},
  {slug:"ford/escape/spark-plug-gap",keyword:"ford escape spark plug gap specs",make:"Ford",model:"2019 Escape 1.5L EcoBoost",category:"Ignition Specs",title:"Ford Escape Spark Plug Gap Specs by Engine",answer:"Ford specifies 0.025–0.029 in (0.65–0.75 mm) for the 2019 Escape 1.5L four-cylinder EcoBoost.",scope:"The exact range applies to the 2019 Escape's 1.5L four-cylinder EcoBoost. The later 1.5L three-cylinder, 1.6L and 2.0L EcoBoost, 2.5L naturally aspirated engine and hybrids have separate rows.",detail:"Confirm the Motorcraft-equivalent plug for the VIN before measuring. Use a wire gauge, handle the fine-wire center electrode carefully and replace a plug whose electrode or insulator is damaged rather than forcing it to the range.",values:[{label:"2019 Escape 1.5L EcoBoost I4",value:"0.025–0.029 in",note:"0.65–0.75 mm; Ford owner manual"},{label:"Firing order",value:"1-3-4-2",note:"Confirms four-cylinder 1.5L"},{label:"2020+ 1.5L three-cylinder",value:"Separate specification",note:"Different engine architecture"},{label:"2.0L / 2.5L / hybrid",value:"Use exact engine row",note:"Do not transfer this gap"}],source:ford2019Escape15,diagram:"spark",engine:true},
  {slug:"chevrolet/colorado/towing-capacity",keyword:"chevy colorado towing capacity chart",make:"Chevrolet",model:"2023 Colorado",category:"Vehicle Specifications",title:"2023 Chevy Colorado Towing Capacity Chart by 2.7L Engine Tune",answer:"Chevrolet rates the 2023 Colorado at 3,500 lb with the 237-hp 2.7L Turbo and as high as 7,700 lb with the 2.7L Turbo Plus or High-Output tune. The off-road ZR2 is capped at 6,000 lb even though it uses the High-Output engine.",scope:"This chart is for the redesigned U.S.-market 2023 Colorado. It does not apply to a 2022-or-earlier truck, a different model year or a truck lacking the equipment required by its trailering label and guide.",detail:"Treat the engine badge as only the first check. Cab, trim, drivetrain, axle, hitch and trailering equipment still matter, and occupants, cargo, accessories and trailer tongue weight consume payload. Confirm the truck's certification labels and owner information before connecting a trailer.",values:[{label:"2.7L Turbo",value:"3,500 lb",note:"237 hp; 259 lb-ft"},{label:"2.7L Turbo Plus",value:"7,700 lb",note:"310 hp; 390 lb-ft"},{label:"2.7L Turbo High-Output",value:"Up to 7,700 lb",note:"310 hp; 430 lb-ft"},{label:"ZR2 with High-Output",value:"6,000 lb max",note:"Off-road configuration has a lower limit"}],source:chevroletColorado2023,diagram:"main"},
  {slug:"dodge/dart/firing-order",keyword:"dodge dart firing order specifications",make:"Dodge",model:"Dart",category:"Firing Order",title:"Dodge Dart Firing Order Specs by Engine",answer:"Modern Dart 1.4L, 2.0L and 2.4L inline-four engines use the 1-3-4-2 firing order; classic Dart engines require separate identification.",scope:"Covers 2013-2016 Dart inline-four engines; classic Slant Six and V8 applications are excluded.",detail:"Cylinder numbering runs from the timing end, but connector and coil layout vary by engine.",values:[{label:"1.4L Turbo I4",value:"1-3-4-2",note:"Verify cylinder orientation"},{label:"2.0L / 2.4L I4",value:"1-3-4-2",note:"Engine-specific ignition hardware"}],source:S.mopar,diagram:"firing",engine:true},
  {slug:"honda/fit/oil-capacity",keyword:"honda fit oil capacity specifications",make:"Honda",model:"2016 Fit 1.5L",category:"Fluid Capacities",title:"2016 Honda Fit Oil Capacity: Exact 1.5L Refill Specs",answer:"Honda specifies 3.5 US qt (3.3 L) when the oil filter is changed on a 2016 Fit 1.5L. An oil-only change is 3.3 US qt (3.1 L).",scope:"These quantities are for the U.S.-market 2016 Fit with the 1,498 cc engine. Other Fit/Jazz generations and markets are not silently grouped into this row; identify the model year before using it.",detail:"Install a new drain-plug washer, refill with the specified 0W-20 oil, run the engine and inspect the filter and drain plug for leaks. Stop the engine, allow drain-back on level ground, and use the dipstick as the final level check rather than treating the published refill quantity as an instruction to overfill.",values:[{label:"Oil and filter change",value:"3.5 US qt",note:"3.3 L; 2016 Honda specification"},{label:"Oil change, filter retained",value:"3.3 US qt",note:"3.1 L"},{label:"Recommended viscosity",value:"SAE 0W-20",note:"Use oil meeting the manual's quality requirement"},{label:"Final verification",value:"Dipstick upper mark",note:"Check after circulation and drain-back"}],source:hondaFit2016,diagram:"oil"},
  {slug:"bmw/x3/brake-rotor-size",keyword:"bmw x3 brake rotor size chart",make:"BMW",model:"X3",category:"Brake Specifications",title:"BMW X3 Brake Rotor Size Chart by Chassis and Brake Option",answer:"BMW X3 rotor diameters vary widely by chassis, engine and brake package, from roughly 307 mm on older/base systems to nearly 400 mm on M Performance applications.",scope:"Covers E83, F25 and G01 X3 brake identification; VIN option code and caliper determine the rotor.",detail:"Match diameter, thickness, minimum thickness, hat height, venting and left/right design.",values:[{label:"Older/base front systems",value:"About 307-330 mm",note:"Chassis dependent"},{label:"Later standard/M Sport fronts",value:"About 348-374 mm",note:"Option dependent"},{label:"X3 M / performance",value:"Larger application-specific rotors",note:"Verify VIN"}],source:S.bmw,diagram:"wheel"},
  {slug:"nissan/titan/towing-capacity",keyword:"nissan titan towing capacity specs",make:"Nissan",model:"Titan",category:"Vehicle Specifications",title:"Nissan Titan Towing Capacity Specs by Configuration",answer:"Titan towing ratings commonly range from roughly 9,000 lb to more than 11,000 lb depending on year, XD/non-XD model, cab, drivetrain and equipment.",scope:"Covers Titan and Titan XD factory ratings; VIN tow guide, payload label and GCWR control.",detail:"Occupants, accessories, cargo and tongue weight reduce available capacity.",values:[{label:"Many standard Titan configurations",value:"About 9,000-9,500 lb",note:"Year/equipment dependent"},{label:"Selected Titan XD configurations",value:"Up to about 11,000+ lb",note:"Exact tow chart required"}],source:S.nissan,diagram:"main"},
  {slug:"jeep/compass/tire-pressure",keyword:"jeep compass tire pressure specs",make:"Jeep",model:"2023 Compass",category:"Vehicle Specifications",title:"2023 Jeep Compass Tire Pressure: Read the Correct Placard",answer:"The correct 2023 Jeep Compass tire pressure is the cold value printed on that vehicle's driver-side B-pillar or door-edge Tire and Loading Information placard. Mopar does not publish one universal internet number for every tire package; its manual uses 33 psi only as a TPMS temperature example, not as a blanket specification.",scope:"Covers the U.S.-market 2023 Compass with factory-approved tires. Trim, original tire size, replacement load rating, market and spare-wheel equipment can change what appears on the placard, so a nearby Compass or a generic 35-psi chart is not authoritative for a particular vehicle.",detail:"Cold means the vehicle has been parked for at least three hours or driven less than 1 mile after that rest. Pressure changes by about 1 psi for each 12°F change in ambient temperature, and normal driving raises pressure; do not bleed a warm tire back to the cold target. The tire sidewall shows the tire's maximum permissible pressure, not Jeep's recommended operating pressure. Set all four road tires from the placard with an accurate gauge, check the spare separately if fitted, reinstall valve caps, and allow the TPMS time to update while driving.",values:[{label:"Normal road-tire target",value:"Use vehicle placard",note:"Driver-side B-pillar or rear door edge"},{label:"Cold definition",value:"Parked 3+ hours",note:"Or driven less than 1 mile after resting"},{label:"Temperature effect",value:"About 1 psi per 12°F",note:"7 kPa per 6.5°C"},{label:"33-psi manual example",value:"Example only",note:"Not a universal Compass specification"},{label:"Tire sidewall number",value:"Maximum, not target",note:"Never substitute for placard pressure"}],source:compass2023,sources:[compass2023,S.mopar],reviewed:"2026-08-21",diagram:"wheel"},
  {slug:"subaru/ascent/towing-capacity",keyword:"subaru ascent towing capacity specs",make:"Subaru",model:"2019 Ascent",category:"Vehicle Specifications",title:"2019 Subaru Ascent Towing Capacity: Factory 5,000-lb Maximum",answer:"Subaru introduced the 2019 Ascent with trailer capacity of up to 5,000 lb. That maximum is configuration- and equipment-dependent; it should not be copied onto another model year or treated as the available capacity after loading the cabin.",scope:"This page is anchored to Subaru's U.S. 2019 launch specifications for the 2.4L turbo BOXER/CVT powertrain. The exact owner's manual and vehicle labels still control hitch requirements, trailer-brake rules, tongue load and the rating for a particular trim.",detail:"Subaru lists Trailer Stability Assist, but an electronic aid cannot increase the mechanical rating or compensate for poor loading. Deduct passengers, cargo, accessories and tongue weight from available payload, keep the trailer within its own ratings, and verify the receiver and electrical connection before departure.",values:[{label:"Maximum trailer capacity",value:"5,000 lb",note:"Factory 2019 model maximum"},{label:"Engine",value:"2.4L turbo BOXER",note:"260 hp; 277 lb-ft"},{label:"Transmission",value:"High-torque Lineartronic CVT",note:"Eight-speed manual mode"},{label:"Stability feature",value:"Trailer Stability Assist",note:"Does not raise the rated limit"}],source:subaruAscent2019,diagram:"main"},
  {slug:"hyundai/palisade/oil-capacity",keyword:"hyundai palisade oil capacity specs",make:"Hyundai",model:"2026 Palisade 3.5L",category:"Fluid Capacities",title:"2026 Hyundai Palisade Oil Capacity and Required 0W-20",answer:"Hyundai specifies 6.13 US qt (5.8 L) for a drain-and-refill on the 2026 Palisade's Smartstream 3.5L GDI V6.",scope:"This is the exact U.S. 2026 LX3 Palisade row. Earlier Palisades use a 3.8L V6 with a different service quantity, so the familiar older-generation number must not be carried forward to the redesigned 3.5L vehicle.",detail:"Use SAE 0W-20 full-synthetic oil meeting API SN PLUS/SP or ILSAC GF-6. Refill short of the listed quantity first, start the engine and check for leaks, shut it down on level ground and allow oil to return to the pan before bringing the dipstick to full. A published refill quantity is not permission to overfill.",values:[{label:"Drain-and-refill quantity",value:"6.13 US qt",note:"5.8 L"},{label:"Engine",value:"Smartstream 3.5 GDI",note:"2026 LX3 Palisade"},{label:"Viscosity",value:"SAE 0W-20",note:"Full synthetic"},{label:"Oil quality",value:"API SN PLUS/SP or ILSAC GF-6",note:"Certification required"}],source:hyundaiPalisade2026,diagram:"oil"},
  {slug:"ford/expedition/wheel-torque",keyword:"ford expedition wheel torque specs",make:"Ford",model:"2021 Expedition",category:"Torque Specs",title:"2021 Ford Expedition Wheel Lug Nut Torque",answer:"Ford specifies 150 lb-ft (204 N·m) for the M14 x 1.5 wheel lug nuts on the 2021 Expedition.",scope:"This exact value is from the 2021 U.S. Expedition owner manual for factory wheel hardware. Earlier generations, aftermarket wheels and replacement fasteners with a different seat design require their own instructions.",detail:"Remove dirt, rust and loose corrosion from the hub pilot and mating faces. Keep the specified threads free of dirt and rust, start each nut by hand, and tighten across the wheel in stages with a calibrated wrench. Ford requires retightening to specification within 100 miles (160 km) after tire rotation, flat-tire service or any other wheel removal.",values:[{label:"Wheel lug nut torque",value:"150 lb-ft",note:"204 N·m"},{label:"Thread size",value:"M14 x 1.5",note:"Factory fastener"},{label:"Recheck interval",value:"Within 100 mi",note:"160 km after wheel disturbance"},{label:"Mounting surface",value:"Clean metal-to-metal contact",note:"Remove corrosion and loose particles"}],source:fordExpedition2021,diagram:"wheel"},
  {slug:"chevrolet/suburban/fuel-tank-capacity",keyword:"chevy suburban fuel tank capacity specs",make:"Chevrolet",model:"2025 Suburban",category:"Fluid Capacities",title:"2025 Chevy Suburban Fuel Tank Capacity: 28 Gallons",answer:"Chevrolet lists the 2025 Suburban's fuel-tank capacity at approximately 28 US gal (106 L) in both 2WD and 4WD form.",scope:"This figure is for the U.S.-market 2025 Suburban. It is a nominal tank capacity, not the amount a normal pump visit should always dispense, and it should not be transferred to an older Suburban 1500/2500 or a Tahoe.",detail:"The low-fuel warning appears while usable reserve remains, and fuel can remain in the tank, lines and module. Temperature, pump shutoff behavior and vehicle angle also change the amount accepted. Do not continue forcing fuel in after the nozzle repeatedly clicks off; use the gauge and range estimate as aids rather than attempting to prove nominal capacity at the pump.",values:[{label:"2025 Suburban 2WD",value:"28 US gal",note:"Approximately 106 L"},{label:"2025 Suburban 4WD",value:"28 US gal",note:"Approximately 106 L"},{label:"Capacity type",value:"Nominal tank volume",note:"Not expected refill amount"},{label:"Tahoe comparison",value:"24 US gal",note:"Do not substitute the shorter model's tank figure"}],source:chevroletSuburban2025,diagram:"oil"},
  {slug:"ram/3500/towing-capacity",keyword:"dodge ram 3500 towing capacity chart",make:"Ram",model:"3500",category:"Vehicle Specifications",title:"Dodge Ram 3500 Towing Capacity Chart by Configuration",answer:"Ram 3500 towing capacity spans well under 20,000 lb to more than 37,000 lb depending on year, engine, axle ratio, cab, drivetrain and fifth-wheel/gooseneck equipment.",scope:"Covers factory Ram 3500 ratings; use the VIN-specific towing chart and door payload label.",detail:"Conventional, fifth-wheel and gooseneck ratings are separate, and available payload often limits pin weight first.",values:[{label:"Conventional towing",value:"Configuration-specific",note:"Often lower than fifth-wheel"},{label:"Properly equipped recent diesel",value:"Up to about 37,000+ lb",note:"Selected configurations only"},{label:"Final authority",value:"VIN tow chart",note:"Check GCWR and payload"}],source:S.mopar,diagram:"main"},
  {slug:"honda/hr-v/spark-plug-torque",keyword:"honda hr-v spark plug torque specs",make:"Honda",model:"HR-V",category:"Ignition Specs",title:"Honda HR-V Spark Plug Torque Specs by Engine",answer:"HR-V spark-plug torque depends on engine and plug seat; many Honda gasket-seat applications fall roughly in the 13-18 lb-ft range.",scope:"Covers common HR-V gasoline engines; North American and international powertrains differ.",detail:"Use the approved plug, clean threads and exact Honda or plug-maker torque/turn-angle instructions.",values:[{label:"Common gasket-seat range",value:"About 13-18 lb-ft",note:"18-25 N-m; verify engine"},{label:"Fine-wire plug",value:"Approved part only",note:"Do not force-adjust electrode"}],source:S.honda,diagram:"spark",engine:true},
  {slug:"bmw/7-series/battery-replacement",keyword:"bmw 7 series battery replacement specs",make:"BMW",model:"7 Series",category:"Electrical Specifications",title:"BMW 7 Series Battery Replacement Specs and Registration",answer:"Modern BMW 7 Series batteries must match AGM/flooded chemistry, Ah capacity, physical size and venting, and require electronic registration after replacement.",scope:"Covers common E65, F01 and G11-era 7 Series systems; VIN equipment and dual-battery configurations must be checked.",detail:"Changing chemistry or capacity may require coding in addition to registration.",values:[{label:"Common main-battery range",value:"About 90-105 Ah",note:"VIN dependent"},{label:"Common later chemistry",value:"AGM",note:"Verify battery label"},{label:"After replacement",value:"Register battery",note:"Code changes if capacity/type differs"}],source:S.bmw,diagram:"main"},
  {slug:"nissan/frontier/oil-capacity",keyword:"nissan frontier oil capacity specs",make:"Nissan",model:"2024 Frontier 3.8L",category:"Fluid Capacities",title:"2024 Nissan Frontier Oil Capacity: With and Without Filter",answer:"Nissan specifies approximately 5.25 US qt (5.0 L) for a 2024 Frontier oil change with a new filter and 5.0 US qt (4.7 L) when the filter is not changed.",scope:"These figures apply to the U.S.-market 2024 Frontier's 3.8L V6. Older 2.5L four-cylinder and 4.0L V6 trucks use different rows, so the familiar capacity from an earlier generation should not be carried forward.",detail:"Nissan recommends Genuine Nissan 0W-20 SP or an equivalent synthetic SAE 0W-20 meeting API SP and ILSAC GF-6A. The manual calls both quantities approximate because oil temperature and drain time affect the refill. Add less than the listed amount first, run the engine, inspect for leaks, shut it down, wait more than 10 minutes on level ground and use the dipstick to establish the final level.",values:[{label:"Oil and filter change",value:"5.25 US qt",note:"5.0 L; 4-3/8 Imperial qt"},{label:"Oil change, filter retained",value:"5.0 US qt",note:"4.7 L; 4-1/8 Imperial qt"},{label:"Recommended viscosity",value:"SAE 0W-20",note:"Synthetic"},{label:"Required quality",value:"API SP / ILSAC GF-6A",note:"Final level by dipstick"}],source:nissanFrontier2024,diagram:"oil"},
  {slug:"jeep/renegade/tire-size",keyword:"jeep renegade tire size specifications",make:"Jeep",model:"Renegade",category:"Vehicle Specifications",title:"Jeep Renegade Tire Size Specs by Year and Trim",answer:"Common Renegade factory sizes include 215/65R16, 215/60R17, 225/55R18 and selected off-road packages with different tires.",scope:"Covers factory Renegade wheels; use the door placard and VIN equipment for exact size, load index and pressure.",detail:"Match load/speed ratings and verify clearance before changing overall diameter.",values:[{label:"Common 16-in size",value:"215/65R16",note:"Verify trim"},{label:"Common 17-in size",value:"215/60R17",note:"Verify year"},{label:"Common 18-in size",value:"225/55R18",note:"Upper trim dependent"}],source:S.mopar,diagram:"wheel"},
  {slug:"subaru/brz/wheel-torque",keyword:"subaru brz wheel torque specs",make:"Subaru",model:"BRZ",category:"Torque Specs",title:"Subaru BRZ Wheel Torque Specs by Generation",answer:"Many Subaru BRZ factory-wheel applications specify approximately 89 lb-ft (120 N-m), but the exact model-year manual controls.",scope:"Covers factory BRZ wheels and original-style nuts; aftermarket wheel instructions may differ.",detail:"Use clean, dry threads, a star pattern and a calibrated torque wrench.",values:[{label:"Common BRZ setting",value:"89 lb-ft",note:"120 N-m; verify year"},{label:"Pattern",value:"Five-lug star",note:"Staged passes"}],source:S.subaru,diagram:"wheel"},
  {slug:"hyundai/genesis/horsepower-by-year",keyword:"hyundai genesis horsepower specs by year",make:"Hyundai",model:"2015 Genesis Sedan",category:"Engine Specifications",title:"2015 Hyundai Genesis Horsepower: 3.8 V6 vs. 5.0 V8",answer:"The U.S.-market 2015 Hyundai Genesis sedan was rated at 311 hp with the 3.8L V6 and 420 hp with the 5.0L V8.",scope:"This chart is deliberately limited to the redesigned 2015 Hyundai-branded Genesis sedan. It does not describe the Genesis Coupe, the earlier 2013–2014 sedan, or later vehicles sold under the standalone Genesis marque.",detail:"Hyundai rated the direct-injected 3.8L Lambda V6 at 311 hp at 6,000 rpm and 293 lb-ft at 5,000 rpm. The direct-injected 5.0L Tau V8 produced 420 hp at 6,000 rpm and 383 lb-ft at 5,000 rpm. Horsepower numbers should be compared at the same model year and using factory ratings, not chassis-dyno results or altered-fuel claims.",values:[{label:"2015 Genesis 3.8",value:"311 hp @ 6,000 rpm",note:"293 lb-ft @ 5,000 rpm"},{label:"2015 Genesis 5.0",value:"420 hp @ 6,000 rpm",note:"383 lb-ft @ 5,000 rpm"},{label:"Fuel note",value:"Factory SAE output",note:"Hyundai notes regular fuel can slightly reduce peak power"},{label:"Genesis Coupe",value:"Separate model",note:"Do not merge coupe engine ratings"}],source:hyundaiGenesis2015,diagram:"main",engine:true},
  {slug:"ford/maverick/towing-capacity",keyword:"ford maverick towing capacity chart",make:"Ford",model:"2022 Maverick",category:"Vehicle Specifications",title:"2022 Ford Maverick Towing Capacity: 2,000 vs. 4,000 lb",answer:"The 2022 Ford Maverick has a 2,000-lb standard maximum towing rating. The 2.0L EcoBoost can reach 4,000 lb when equipped with the available 4K Tow Package.",scope:"These are U.S. 2022 model-year maximum ratings from Ford's technical specifications. A 2.0L engine by itself does not prove the truck has the 4K package, and the standard 2.5L hybrid row remains 2,000 lb.",detail:"Confirm the powertrain and factory tow package from the VIN/build data, then use the certification label to calculate remaining payload. Trailer tongue weight, passengers, bed cargo and accessories all consume payload, so the advertised maximum does not mean every 4K-equipped truck can carry every combination of people and cargo while towing 4,000 lb.",values:[{label:"2.5L hybrid FWD",value:"2,000 lb max",note:"Standard 2022 rating"},{label:"2.0L EcoBoost",value:"2,000 lb standard",note:"FWD or AWD without qualifying 4K setup"},{label:"2.0L + 4K Tow Package",value:"4,000 lb max",note:"Factory package required"},{label:"Maximum payload",value:"Up to 1,500 lb",note:"Actual door-label payload varies"}],source:fordMaverick2022,diagram:"main"},
  {slug:"chevrolet/camaro/horsepower-by-year",keyword:"chevy camaro horsepower specs by year",make:"Chevrolet",model:"Camaro",category:"Engine Specifications",title:"Chevy Camaro Horsepower Specs by Year and Generation",answer:"Camaro factory output ranges from modest emissions-era ratings to 650 hp for the sixth-generation ZL1, with gross/net standards and engine options affecting comparisons.",scope:"Covers selected U.S. factory ratings; year, engine, trim and rating standard must be identified.",detail:"Pre-1972 gross ratings should not be compared directly with later SAE net ratings.",values:[{label:"1967 Z/28 302",value:"290 hp gross",note:"Period advertised rating"},{label:"1985 IROC-Z 5.0 TPI",value:"215 hp",note:"Selected configuration"},{label:"1993 Z28",value:"275 hp",note:"LT1"},{label:"2010 SS",value:"400-426 hp",note:"Transmission dependent"},{label:"2016 SS",value:"455 hp",note:"LT1"},{label:"2017-2024 ZL1",value:"650 hp",note:"Supercharged LT4"}],source:S.gm,diagram:"main",engine:true},
  {slug:"toyota/crown/oil-capacity",keyword:"toyota crown oil capacity specs",make:"Toyota",model:"2024 Crown",category:"Fluid Capacities",title:"2024 Toyota Crown Oil Capacity: 2.5L vs. Hybrid MAX",answer:"For the 2024 North American Crown, the 2.5L A25A-FXS hybrid uses 4.5 US qt (4.3 L) with filter, while the 2.4L turbo T24A-FTS Hybrid MAX uses 5.6 US qt (5.3 L) with filter.",scope:"These figures apply to the 2024 U.S./Canada Crown crossover sedan and must be matched by engine code. They do not cover the Crown Signia, older imported Crown generations, Japanese-market body styles or another Toyota that happens to use a related engine.",detail:"The two current powertrains also use different oil specifications: the naturally aspirated 2.5L hybrid row calls for JASO GLV-1 SAE 0W-8, while the 2.4L turbo row calls for the model-year Toyota-approved grade shown in its manual. Toyota treats both capacities as drain-and-refill references. Warm the engine, shut the hybrid system off, wait about five minutes on level ground, add below the total first, then finish at the dipstick instead of forcing the whole bottle count into the crankcase.",values:[{label:"2024 XLE/Limited 2.5L A25A-FXS",value:"4.5 US qt",note:"4.3 L with filter"},{label:"2024 Platinum 2.4L T24A-FTS",value:"5.6 US qt",note:"5.3 L with filter"},{label:"2.5L without filter",value:"4.2 US qt",note:"4.0 L; normal service should replace filter"},{label:"2.4L without filter",value:"5.3 US qt",note:"5.0 L"},{label:"2.5L oil viscosity",value:"SAE 0W-8",note:"JASO GLV-1 in cited manual"}],source:toyotaCrown2024,sources:[toyotaCrown2024,S.toyota],reviewed:"2026-08-21",diagram:"oil"},
  {slug:"dodge/durango/horsepower",keyword:"dodge durango horsepower specs chart",make:"Dodge",model:"2023 Durango",category:"Engine Specifications",title:"2023 Dodge Durango Horsepower Chart by Engine and Trim",answer:"For 2023, Dodge rates the Durango at up to 295 hp with the 3.6L V6, 360 hp with the 5.7L HEMI, 475 hp with the 6.4L SRT 392 and 710 hp with the supercharged 6.2L SRT Hellcat.",scope:"This chart is specific to the U.S.-market 2023 Durango lineup. Similar trim names in other years can have different availability, and the Hellcat figure must not be assigned to an R/T or SRT 392.",detail:"Factory torque is equally important: the 3.6L is rated at up to 260 lb-ft, the 5.7L at 390 lb-ft, the 6.4L at 470 lb-ft and the Hellcat at 645 lb-ft. Horsepower alone does not establish towing capacity; engine cooling, axle ratio, brakes, hitch equipment, GCWR and the vehicle's payload label remain separate limits.",values:[{label:"3.6L Pentastar V6",value:"Up to 295 hp",note:"260 lb-ft; SXT/GT/Citadel applications"},{label:"5.7L HEMI V8",value:"360 hp",note:"390 lb-ft; R/T and optional Citadel"},{label:"6.4L SRT 392 V8",value:"475 hp",note:"470 lb-ft"},{label:"6.2L supercharged Hellcat",value:"710 hp",note:"645 lb-ft"}],source:dodgeDurango2023,diagram:"main",engine:true},
  {slug:"honda/ridgeline/towing-capacity",keyword:"honda ridgeline towing capacity specs",make:"Honda",model:"2024 Ridgeline",category:"Vehicle Specifications",title:"2024 Honda Ridgeline Towing Capacity and Tongue-Weight Limit",answer:"Honda lists a 5,000-lb maximum towing capacity and a 600-lb maximum tongue weight for the 2024 Ridgeline with the described Class III towing equipment.",scope:"These are 2024 U.S. brochure figures. They do not automatically apply to an earlier front-wheel-drive Ridgeline, a missing towing component, an overloaded truck or a trailer whose own rating is lower.",detail:"Tongue weight is part of the truck's load, so passengers, cargo, bed accessories and hitch load must fit the payload shown for the actual vehicle. Confirm the receiver, ball mount, ball, safety chains, seven-pin connection and any brake-controller requirement. Keep both gross trailer weight and tongue weight within their separate limits.",values:[{label:"Maximum towing capacity",value:"5,000 lb",note:"2024 Honda brochure"},{label:"Maximum tongue weight",value:"600 lb",note:"Separate hard limit"},{label:"Receiver class",value:"Class III",note:"Honda towing equipment"},{label:"Electrical connection",value:"Verify trailer connector and brakes",note:"Trailer-specific requirements still apply"}],source:hondaRidgeline2024,diagram:"main"},
  {slug:"bmw/m5/horsepower-by-year",keyword:"bmw m5 horsepower specs by year",make:"BMW",model:"M5",category:"Engine Specifications",title:"BMW M5 Horsepower Specs by Generation",answer:"U.S.-market BMW M5 output increased from 256 hp in the E28 to more than 700 hp in the latest hybrid generation.",scope:"Covers selected U.S. factory ratings; market, Competition/CS package and rating standard matter.",detail:"European and U.S. cars can have different ratings within one chassis.",values:[{label:"E28 M5",value:"256 hp",note:"U.S. rating"},{label:"E34 M5",value:"310 hp",note:"U.S. rating"},{label:"E39 M5",value:"394 hp",note:"4.9L V8"},{label:"E60 M5",value:"500 hp",note:"5.0L V10"},{label:"F10 M5",value:"560 hp",note:"Launch rating"},{label:"F90 M5 Competition",value:"617 hp",note:"Factory rating"},{label:"F90 M5 CS",value:"627 hp",note:"Factory rating"},{label:"G90 M5",value:"717 hp",note:"System output"}],source:S.bmw,diagram:"main",engine:true},
  {slug:"nissan/murano/spark-plug-gap",keyword:"nissan murano spark plug gap specs",make:"Nissan",model:"Murano",category:"Ignition Specs",title:"Nissan Murano Spark Plug Gap Specs by Generation",answer:"Many VQ35DE-powered Murano applications use a nominal plug gap around 1.1 mm (0.043 in), but approved plug and model year control.",scope:"Covers common Murano 3.5L V6 applications; later powertrain revisions must be verified.",detail:"Use the approved fine-wire plug and do not force-adjust its center electrode.",values:[{label:"Common VQ35DE nominal gap",value:"1.1 mm",note:"0.043 in; verify year"},{label:"Replacement plug",value:"Approved part number",note:"Reach, seat and heat range matter"}],source:S.nissan,diagram:"spark",engine:true},
  {slug:"jeep/patriot/wheel-torque",keyword:"jeep patriot wheel torque specs",make:"Jeep",model:"2017 Patriot",category:"Torque Specs",title:"2017 Jeep Patriot Lug Nut Torque and Tightening Pattern",answer:"The 2017 Jeep Patriot user guide specifies 100 ft-lb (135 N·m) for the wheel nuts/bolts.",scope:"This exact row applies to a 2017 Patriot using the factory M12 x 1.5 fasteners and their original conical-seat wheel interface. Aftermarket wheels can specify different hardware or a different procedure.",detail:"Inspect the hub and wheel mounting faces and remove loose corrosion. Keep the threads free of dirt and oil, start every nut by hand, lower the vehicle enough to prevent rotation, then tighten in a star pattern until every nut has been torqued twice. Mopar calls for another torque check after 25 miles (40 km).",values:[{label:"Wheel fastener torque",value:"100 ft-lb",note:"135 N·m; 2017 Mopar guide"},{label:"Thread size",value:"M12 x 1.5",note:"Factory hardware"},{label:"Socket size",value:"19 mm",note:"Use a six-point socket"},{label:"Post-service recheck",value:"After 25 mi",note:"40 km"}],source:jeepPatriot2017,diagram:"wheel"},
  {slug:"subaru/wrx/oil-capacity",keyword:"subaru wrx oil capacity specifications",make:"Subaru",model:"2018 WRX / WRX STI",category:"Fluid Capacities",title:"2018 Subaru WRX Oil Capacity: WRX vs. WRX STI",answer:"Subaru specifies 5.4 US qt (5.1 L) for a 2018 WRX oil-and-filter change and 4.5 US qt (4.3 L) for the 2018 WRX STI. The two turbo models do not share one refill quantity.",scope:"These figures are limited to the 2018 U.S. WRX with the FA20DIT and WRX STI with the EJ257. They should not be transferred to the later FA24 WRX, an earlier EJ-series car or another market without checking its manual.",detail:"Subaru calls for synthetic SAE 5W-30 meeting API SN with Resource Conserving wording or ILSAC GF-5 in this guide. Add less than the stated service quantity first, run the engine and inspect for leakage, wait on level ground for drain-back, and finish at the full mark. The STI's lower published quantity is not a typo and the WRX figure is not a safe substitute.",values:[{label:"2018 WRX oil and filter",value:"5.4 US qt",note:"5.1 L; 4.5 Imperial qt"},{label:"2018 WRX STI oil and filter",value:"4.5 US qt",note:"4.3 L; 3.8 Imperial qt"},{label:"Specified viscosity",value:"SAE 5W-30 synthetic",note:"Both guide rows"},{label:"Oil quality",value:"API SN RC or ILSAC GF-5",note:"Final level by dipstick"}],source:subaruWrx2018,diagram:"oil"},
  {slug:"hyundai/elantra-n/horsepower",keyword:"hyundai elantra n horsepower specs",make:"Hyundai",model:"2022 Elantra N",category:"Engine Specifications",title:"2022 Hyundai Elantra N Horsepower and N Grin Shift Output",answer:"Hyundai rates the 2022 Elantra N's 2.0L turbo engine at 276 hp and 289 lb-ft. On the eight-speed DCT model, N Grin Shift briefly raises output to 286 hp.",scope:"This factory rating applies to the North American 2022 Elantra N. The Elantra N Line is a different trim and powertrain; 286 hp is a temporary DCT overboost figure, not the engine's continuous rating and not a manual-transmission feature.",detail:"Maximum standard power is delivered from 5,500–6,000 rpm, while the 289 lb-ft torque plateau is listed from 2,100–4,700 rpm. Pressing the NGS control on an eligible DCT car increases turbo boost and transmission response for up to 20 seconds. Conditions and safeguards in the owner's manual still apply.",values:[{label:"Standard maximum output",value:"276 hp",note:"5,500–6,000 rpm"},{label:"Peak torque",value:"289 lb-ft",note:"2,100–4,700 rpm"},{label:"N Grin Shift output",value:"286 hp",note:"Up to 20 seconds; DCT only"},{label:"Six-speed manual",value:"276 hp",note:"No DCT NGS overboost function"}],source:hyundaiElantraN2022,diagram:"main",engine:true},
  {slug:"ford/transit/oil-capacity",keyword:"ford transit oil capacity chart",make:"Ford",model:"2022 Transit",category:"Fluid Capacities",title:"2022 Ford Transit Oil Capacity: Duratec vs. EcoBoost",answer:"Ford lists 6.0 US qt (5.7 L) including the filter for both gasoline engines in the 2022 U.S. full-size Transit: the naturally aspirated 3.5L Duratec and the 3.5L EcoBoost.",scope:"This exact chart is limited to the 2022 U.S./Canada full-size Transit. It does not apply to Transit Connect, E-Series, European-market 2.0L EcoBlue or 2.2L/3.2L diesels, another model year, or a replacement oil pan. Identify the engine and market even though both cited gasoline rows happen to share capacity.",detail:"Shared capacity does not mean shared oil identity. The 2022 Ford rows call for SAE 5W-30 meeting WSS-M2C961-A1, with SAE 0W-30 meeting WSS-M2C963-A1 identified for extremely cold climates. Ford notes that approximately 1.0 qt moves the dipstick from minimum to nominal and warns against filling above maximum. After replacing the filter, add less than six quarts, run the engine, inspect for leaks, wait for drain-back on level ground and approach the full mark gradually.",values:[{label:"2022 3.5L Duratec with filter",value:"6.0 US qt",note:"5.7 L"},{label:"2022 3.5L EcoBoost with filter",value:"6.0 US qt",note:"5.7 L"},{label:"Specified oil",value:"SAE 5W-30",note:"Ford WSS-M2C961-A1"},{label:"Extreme-cold alternative",value:"SAE 0W-30",note:"WSS-M2C963-A1 at -22°F/-30°C or below"},{label:"Dipstick MIN-to-nominal",value:"About 1.0 US qt",note:"0.9 L in Ford manual"}],source:fordTransit2022,sources:[fordTransit2022,S.ford],reviewed:"2026-08-21",diagram:"oil"},
  {slug:"chevrolet/blazer/towing-capacity",keyword:"chevy blazer towing capacity specs",make:"Chevrolet",model:"2023 Blazer",category:"Vehicle Specifications",title:"2023 Chevy Blazer Towing Capacity: Factory 4,500-lb Maximum",answer:"The 2023 Chevrolet Trailering Guide lists a maximum trailer-weight rating of 4,500 lb for a properly equipped Blazer. That is a model maximum, not a promise that every Blazer can tow 4,500 lb.",scope:"This page covers the modern U.S.-market 2023 Blazer crossover, not the classic K5 or Trailblazer. Use the actual vehicle's engine, drivetrain, trailering equipment, payload label and owner information to establish its usable limit.",detail:"Start with the factory rating, then account for passengers, cargo, accessories and hitch load. Trailer tongue weight counts against available vehicle payload. Confirm an approved hitch, wiring, cooling provisions and any trailer-brake requirement before towing; never infer the maximum from appearance or engine displacement alone.",values:[{label:"2023 Blazer model maximum",value:"4,500 lb",note:"When properly equipped"},{label:"Rating type",value:"Maximum trailer weight",note:"Not payload or GCWR"},{label:"Payload deduction",value:"People + cargo + tongue weight",note:"All consume available vehicle capacity"},{label:"Final check",value:"Vehicle labels and owner guide",note:"Configuration-specific limits control"}],source:chevroletTrailering2023,diagram:"main"},
  {slug:"toyota/prius/tire-pressure",keyword:"toyota prius tire pressure specifications",make:"Toyota",model:"Prius",category:"Vehicle Specifications",title:"Toyota Prius Tire Pressure Specs by Generation",answer:"Many Prius factory tire packages specify mid-30s psi cold, often with the front a few psi higher than the rear; the door placard controls.",scope:"Covers factory Prius tires; Prime, wheel size and model year can change values.",detail:"Do not use the tire sidewall maximum as the normal vehicle setting.",values:[{label:"Common front range",value:"About 35-36 psi cold",note:"Verify placard"},{label:"Common rear range",value:"About 33-35 psi cold",note:"May differ from front"},{label:"Prius Prime / larger wheels",value:"Trim-specific",note:"Use door label"}],source:S.toyota,diagram:"wheel"},
  {slug:"ram/1500/spark-plug-gap",keyword:"dodge ram 1500 spark plug gap specs",make:"Ram",model:"2011 1500",category:"Ignition Specs",title:"2011 Ram 1500 Spark Plug Gap Specs by Engine",answer:"For the 2011 Ram 1500, Mopar lists 0.043 in (1.09 mm) for both the 3.7L V6 and 5.7L HEMI. The 4.7L V8 is different: its upper plugs are 0.039 in (0.99 mm) and its lower plugs are 0.051 in (1.30 mm).",scope:"These values are specific to the 2011 Ram 1500 engine and plug rows in the factory guide. They are not a universal specification for later 3.6L Pentastar trucks, later 5.7L plug revisions, or any Cummins diesel.",detail:"Match the engine and the listed replacement plug before measuring. The 5.7L and 4.7L use two plugs per cylinder; on the 4.7L, upper and lower positions intentionally use different plugs and gaps. A fine-wire plug with a damaged electrode should be replaced, not aggressively bent to a target.",values:[{label:"3.7L V6",value:"0.043 in",note:"1.09 mm; ZFR6F-11G"},{label:"5.7L HEMI",value:"0.043 in",note:"1.09 mm; LZFR5C-11"},{label:"4.7L upper bank",value:"0.039 in",note:"0.99 mm; FR8TE2"},{label:"4.7L lower bank",value:"0.051 in",note:"1.30 mm; FR8T1332"}],source:ram1500Guide2011,diagram:"spark",engine:true},
  {slug:"honda/civic/brake-rotor-torque",keyword:"honda civic brake rotor torque specs",make:"Honda",model:"Civic",category:"Brake Specifications",title:"Honda Civic Brake Rotor and Caliper Torque Specs",answer:"There is no single Civic brake-rotor torque: rotor screws, caliper pins, carrier bolts and wheel nuts each use separate generation-specific values.",scope:"Covers Civic brake-service identification; body style, trim, front/rear axle and brake package must be matched.",detail:"Do not apply wheel-nut torque to the rotor retaining screw or caliper hardware.",values:[{label:"Rotor retaining screws",value:"Low torque",note:"Model-year specific"},{label:"Caliper guide pins",value:"Caliper-specific",note:"Front/rear differ"},{label:"Carrier bolts",value:"Higher separate torque",note:"Check reuse/threadlocker"},{label:"Wheel nuts",value:"Separate final specification",note:"Use exact Civic manual"}],source:S.honda,diagram:"wheel"},
  {slug:"bmw/4-series/wheel-torque",keyword:"bmw 4 series wheel torque specs",make:"BMW",model:"4 Series",category:"Torque Specs",title:"BMW 4 Series Wheel Bolt Torque Specs by Chassis",answer:"Most modern BMW 4 Series factory-wheel applications use 103 lb-ft (140 N-m), subject to chassis and accessory-wheel verification.",scope:"Covers F32/F36 and G22-era standard factory wheels; M4 and accessory wheels require their own instructions.",detail:"Use the correct BMW seat geometry, clean threads and a calibrated wrench.",values:[{label:"Common 4 Series setting",value:"103 lb-ft",note:"140 N-m"},{label:"M4/accessory wheels",value:"Check exact instructions",note:"Do not assume base value"}],source:S.bmw,diagram:"wheel"},
  {slug:"nissan/armada/towing-capacity",keyword:"nissan armada towing capacity chart",make:"Nissan",model:"2024 Armada",category:"Vehicle Specifications",title:"2024 Nissan Armada Towing Capacity and Tongue Weight",answer:"Nissan rates the properly equipped 2024 Armada to tow up to 8,500 lb, with a published maximum tongue-weight capacity of 850 lb.",scope:"These are 2024 U.S.-market model maximums, not automatic ratings for every load combination. The vehicle certification label, payload label, receiver, ball mount, trailer brakes, cargo, passenger load and the exact owner's/towing guide must all permit the planned setup. Earlier Armadas and the redesigned 2025 twin-turbo model require their own publications.",detail:"Tongue weight is part of the Armada's carried load. Subtract passengers, luggage, accessories and tongue weight from the door-label payload allowance; then verify that actual trailer weight, GCWR, front and rear GAWR, receiver rating and tire limits are all respected. Weigh the loaded combination rather than relying on an empty-trailer brochure figure. Keep approximately the guide-recommended share of trailer weight on the hitch, use trailer brakes and weight-distributing equipment where Nissan requires them, and never raise a limit by installing a stronger aftermarket hitch.",values:[{label:"2024 maximum trailer weight",value:"8,500 lb",note:"Properly equipped model maximum"},{label:"Maximum tongue-weight capacity",value:"850 lb",note:"Counts against available payload"},{label:"Payload allowance",value:"Door-label specific",note:"Passengers + cargo + tongue weight"},{label:"Loaded trailer weight",value:"Scale-verified",note:"Trailer, fluids, gear and accessories"},{label:"Controlling limits",value:"GVWR / GAWR / GCWR",note:"None may be exceeded"}],source:nissanArmada2024,sources:[nissanArmada2024,nissanTowing2024,S.nissan],reviewed:"2026-08-21",diagram:"main"},
  {slug:"jeep/grand-wagoneer/towing-capacity",keyword:"jeep grand wagoneer towing specs",make:"Jeep",model:"2025 Grand Wagoneer L",category:"Vehicle Specifications",title:"2025 Jeep Grand Wagoneer L Towing Capacity: 9,450-lb Maximum",answer:"The 2025 Jeep Grand Wagoneer L is rated to tow up to 9,450 lb (4,286 kg) in the Stellantis Canada fact sheet. This is the long-wheelbase model's properly equipped maximum, not a universal rating for every Wagoneer-family SUV.",scope:"This page is deliberately limited to the 2025 Grand Wagoneer L specification published for Canada. Standard-wheelbase Grand Wagoneer, regular Wagoneer, another year or a U.S.-market configuration must be checked in its own towing chart.",detail:"The Heavy-Duty Trailer Tow Package and exact configuration matter. Verify the certification label, payload, GCWR, receiver rating, axle and cooling equipment on the vehicle. Occupants, luggage, accessories and tongue weight can make payload the limiting number before the advertised trailer maximum is reached.",values:[{label:"Maximum trailer weight",value:"9,450 lb",note:"2025 Grand Wagoneer L"},{label:"Metric rating",value:"4,286 kg",note:"Factory published conversion"},{label:"Body",value:"Long wheelbase",note:"Do not transfer to standard-wheelbase model"},{label:"Required check",value:"Equipment + payload + GCWR",note:"All limits must be satisfied"}],source:grandWagoneerL2025,diagram:"main"},
  {slug:"hyundai/sonata/spark-plug-gap",keyword:"hyundai sonata spark plug gap specs",make:"Hyundai",model:"Sonata",category:"Ignition Specs",title:"Hyundai Sonata Spark Plug Gap Specs by Engine",answer:"Sonata spark-plug gaps vary by engine; many naturally aspirated applications use roughly 0.039-0.043 in, while turbo engines commonly use narrower approved gaps.",scope:"Covers common Sonata gasoline engines; engine code, turbo status, hybrid and model year must be matched.",detail:"Use the approved fine-wire plug and do not force-adjust its center electrode.",values:[{label:"Many naturally aspirated engines",value:"About 0.039-0.043 in",note:"1.0-1.1 mm"},{label:"Many turbo engines",value:"Narrower engine-specific gap",note:"Check approved plug"}],source:S.hyundai,diagram:"spark",engine:true},
  {slug:"ford/bronco/wheel-torque",keyword:"ford bronco wheel torque specifications",make:"Ford",model:"2022 Bronco",category:"Torque Specs",title:"2022 Ford Bronco Wheel Nut Torque: 100 lb-ft",answer:"Ford specifies 100 lb-ft (135 N·m) for the M12 x 1.5 wheel nuts on the 2022 full-size Bronco.",scope:"This is the factory specification for the 2022 Bronco, not the Bronco Sport and not a classic Bronco. Accessory beadlock-capable wheel ring hardware is a separate component and must not be assigned the wheel-nut value.",detail:"Remove dirt, rust and loose corrosion from the wheel pilot bore and both mounting faces. Use replacement fasteners with the correct seat, start them by hand and tighten across the wheel in stages with a calibrated wrench. Ford requires the wheel nuts to be retightened to specification within 100 miles (160 km) after a wheel disturbance such as rotation or removal.",values:[{label:"Wheel nut torque",value:"100 lb-ft",note:"135 N·m; 2022 Ford manual"},{label:"Thread size",value:"M12 x 1.5",note:"Factory wheel nuts"},{label:"Recheck interval",value:"Within 100 mi",note:"160 km after wheel disturbance"},{label:"Bronco Sport",value:"Separate manual",note:"Do not transfer this row"}],source:fordBronco2022,diagram:"wheel"},
  {slug:"chevrolet/corvette/horsepower-by-year",keyword:"chevy corvette horsepower specs by year",make:"Chevrolet",model:"Corvette",category:"Engine Specifications",title:"Chevy Corvette Horsepower Specs by Year and Generation",answer:"Corvette output spans from early gross-rated V8s to 1,064 hp for the 2025 ZR1, with generation, engine and rating standard controlling comparisons.",scope:"Covers selected U.S. factory ratings; trim and model year must be matched.",detail:"Pre-1972 gross ratings are not directly comparable to SAE net ratings.",values:[{label:"1955 265 V8",value:"195 hp gross",note:"Period rating"},{label:"1969 ZL1",value:"430 hp gross advertised",note:"Period rating"},{label:"1990 ZR-1",value:"375 hp",note:"LT5"},{label:"2001 Z06",value:"385 hp",note:"Later C5 Z06 reached 405"},{label:"2009 ZR1",value:"638 hp",note:"Supercharged LS9"},{label:"2020 Stingray",value:"490-495 hp",note:"Exhaust dependent"},{label:"2023 Z06",value:"670 hp",note:"LT6"},{label:"2025 ZR1",value:"1,064 hp",note:"Factory rating"}],source:S.gm,diagram:"main",engine:true},
  {slug:"toyota/sienna/oil-capacity",keyword:"toyota sienna oil capacity specs",make:"Toyota",model:"Sienna",category:"Fluid Capacities",title:"Toyota Sienna Oil Capacity by Engine and Towing Package",answer:"Toyota's 2020 Sienna 3.5L lists 5.8 US qt (5.5 L) with filter when equipped with the towing package and 5.7 US qt (5.4 L) without it. The 2021-and-newer Sienna changed to a 2.5L hybrid and uses a separate, lower-capacity row that must not be filled from the V6 chart.",scope:"The exact V6 figures below come from the 2020 North American Sienna manual. The current hybrid row is anchored to the 2024 Sienna Hybrid manual. Earlier 3.0L/3.3L vans, older 2GR-FE years, regional models and another model year require their matching manual rather than a generation-wide guess.",detail:"Toyota changed both engine family and powertrain architecture for 2021. On the 2020 V6, the towing-package distinction changes the filter refill by 0.1 qt; without-filter capacity is 5.6 qt. On the fourth-generation A25A-FXS hybrid, the filter-change reference is 4.5 qt (4.3 L). Warm the engine, shut it down or switch the hybrid system off, wait more than five minutes on level ground, add below the reference quantity first and finish from the dipstick.",values:[{label:"2020 3.5L with towing package",value:"5.8 US qt",note:"5.5 L with filter"},{label:"2020 3.5L without towing package",value:"5.7 US qt",note:"5.4 L with filter"},{label:"2020 without filter",value:"5.6 US qt",note:"5.3 L; normal service should replace filter"},{label:"2021+ 2.5L hybrid",value:"4.5 US qt",note:"4.3 L with filter in cited 2024 manual"},{label:"Generation break",value:"2021 model year",note:"V6 ended; A25A-FXS hybrid began"}],source:toyotaSienna2020,sources:[toyotaSienna2020,toyotaSienna2024,S.toyota],reviewed:"2026-08-21",diagram:"oil"},
  {slug:"dodge/grand-caravan/spark-plug-specs",keyword:"dodge grand caravan spark plug specs",make:"Dodge",model:"Grand Caravan",category:"Ignition Specs",title:"Dodge Grand Caravan Spark Plug Gap and Torque Specs",answer:"Grand Caravan spark-plug gap and torque vary among 3.3L, 3.8L, 4.0L and 3.6L engines; many later Pentastar applications use approved plugs near 0.043 in.",scope:"Covers Grand Caravan gasoline engines; model year, engine and plug seat must be identified.",detail:"Match part number, reach, heat range, gap and seat-specific torque; do not use anti-seize unless specified.",values:[{label:"Many 3.6L Pentastar applications",value:"About 0.043 in gap",note:"Verify approved plug"},{label:"3.3L / 3.8L / 4.0L",value:"Engine-specific",note:"Different plug and torque"}],source:S.mopar,diagram:"spark",engine:true},
  {slug:"bmw/x1/wheel-torque",keyword:"bmw x1 wheel torque specifications",make:"BMW",model:"X1",category:"Torque Specs",title:"BMW X1 Wheel Bolt Torque Specs by Chassis",answer:"Many modern BMW X1 factory-wheel applications use 103 lb-ft (140 N-m), but chassis and accessory-wheel instructions control.",scope:"Covers E84, F48 and U11 X1 factory wheels; verify VIN and wheel package.",detail:"Use correct seat geometry and clean threads, then tighten in an opposite-side pattern.",values:[{label:"Common modern setting",value:"103 lb-ft",note:"140 N-m; verify chassis"},{label:"Accessory wheels",value:"Wheel-specific instructions",note:"May differ"}],source:S.bmw,diagram:"wheel"},
  {slug:"nissan/versa/tire-pressure",keyword:"nissan versa tire pressure specs",make:"Nissan",model:"Versa",category:"Vehicle Specifications",title:"Nissan Versa Tire Pressure Specs by Year",answer:"Many Versa factory tire packages specify roughly 33-36 psi cold, but model year, trim and tire size determine the placard values.",scope:"Covers factory Versa sedan/hatchback tires; use the driver's-door placard.",detail:"The tire sidewall maximum is not the normal vehicle target.",values:[{label:"Common Versa range",value:"About 33-36 psi cold",note:"Verify placard"},{label:"Temporary spare",value:"Separate high pressure",note:"Check spare label"}],source:S.nissan,diagram:"wheel"},
  {slug:"jeep/wrangler/axle-torque",keyword:"jeep wrangler axle torque specs",make:"Jeep",model:"Wrangler",category:"Torque Specs",title:"Jeep Wrangler Axle Torque Specs by Axle and Fastener",answer:"Wrangler axle torque is not one value: axle nuts, shaft bolts, differential covers, bearing caps, pinion nuts and suspension links use separate procedures.",scope:"Covers Dana axle service across YJ, TJ, JK and JL generations; identify axle model, year and fastener.",detail:"Pinion-nut tightening sets bearing preload and must never be replaced by a generic final torque.",values:[{label:"Front axle/hub nut",value:"Generation-specific",note:"Unit bearing/shaft design matters"},{label:"Differential cover",value:"Axle-specific low torque",note:"Sealant/gasket dependent"},{label:"Bearing caps",value:"Internal axle specification",note:"Keep side and orientation"},{label:"Pinion nut",value:"Preload procedure",note:"Measure rotating torque"}],source:S.mopar,diagram:"main"},
  {slug:"subaru/outback/tire-pressure",keyword:"subaru outback tire pressure specifications",make:"Subaru",model:"Outback",category:"Vehicle Specifications",title:"Subaru Outback Tire Pressure Specs by Year and Trim",answer:"Many Outback factory tire packages specify mid-30s psi cold, often with different front and rear values; the door placard controls.",scope:"Covers factory Outback tires; Wilderness, wheel size, load and model year can change values.",detail:"Check pressure cold and use the placard, not the tire sidewall maximum.",values:[{label:"Common front range",value:"About 35-36 psi cold",note:"Verify placard"},{label:"Common rear range",value:"About 33-35 psi cold",note:"May differ from front"},{label:"Wilderness/special trims",value:"Trim-specific",note:"Use door label"}],source:S.subaru,diagram:"wheel"},
];
function makePage(j:Job):SpecRecord{const points=j.diagram==="firing"?(j.values[0]?.value.match(/\d/g)??["ID"]):j.values.map((_,i)=>String(i+1));return {slug:j.slug,keyword:j.keyword,make:j.make,model:j.model,category:j.category,title:j.title,metaDescription:`${j.title} with application chart, generation boundaries, verification steps and official manufacturer lookup.`,answer:j.answer,scope:j.scope,detail:j.detail,values:j.values,sources:j.sources??[j.source],reviewed:j.reviewed??reviewed,featureImage:j.engine?engineImage:vehicleImage,featureOverlay:true,diagram:{type:j.diagram??"main",title:`Interactive ${j.model} specification guide`,caption:"Orientation aid only. Match the VIN, engine, trim and manufacturer document before use.",points},intro:[j.answer,j.scope],steps:["Identify model year, VIN, engine, trim, drivetrain and factory option codes.","Match the correct application row to the manufacturer document and physical component.","Record the verified value, units and scope before service, towing, loading or parts purchase."],sections:[{heading:`Application boundaries for ${j.model}`,paragraphs:[j.scope,j.detail]}],faqs:[{q:`What are the ${j.keyword}?`,a:j.answer},{q:"Why does the specification vary?",a:j.scope},{q:"What should be verified first?",a:`${j.detail} Confirm the exact application in the linked manufacturer source.`}]};}
export const generalVehicleBatch2Specs:SpecRecord[]=jobs.map(makePage);
